17	import { ZimmSearchInput } from 'app/components/ui-kits/atoms/zimmSearchInput/zimmSearchInput.css';
18	import { ZimmProductContent } from 'app/components/ui-kits/molecules/zimmProductContent/zimmProductContent.css';
19	import { ZimmProductDescription } from 'app/components/ui-kits/atoms/zimmProductDescription/zimmProductDescription.css';
20	import { ZimmProductPrice } from 'app/components/ui-kits/atoms/zimmProductPrice/zimmProductPrice.css';
21	import { ZimmProductStyleCode } from 'app/components/ui-kits/atoms/zimmProductStyleCode/zimmProductStyleCode.css';
